cssCode:
.flip-wrap { width: 100%; padding: 120vh 0; display: flex; justify-content: center; perspective: 1000px; }
.flip-card {
  width: 220px; height: 150px;
  background: rgba(255, 255, 255, 0.1); backdrop-filter: blur(10px);
  border: 1px solid rgba(0, 255, 204, 0.5); border-radius: 20px;
  display: flex; align-items: center; justify-content: center;
  color: #00ffcc; font-weight: bold; font-family: sans-serif;
  transform: rotateY(90deg) scale(0.8); opacity: 0;
  transition: all 1s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  box-shadow: 0 0 0 rgba(0, 255, 204, 0);
}
.flip-card.visible {
  transform: rotateY(0deg) scale(1); opacity: 1;
  box-shadow: 0 10px 40px rgba(0, 255, 204, 0.6);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'flip-wrap';

const card = document.createElement('div');
card.className = 'flip-card';
card.innerText = '3D FLIPPED!';

wrap.appendChild(card);
c.appendChild(wrap);

const obs2 = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
    } else {
      entry.target.classList.remove('visible');
    }
  });
});
obs2.observe(card);
